mapper.select:
SELECT COUNT(*)
FROM refund
WHERE refund_no = #{refundNo}

mapper.update:
UPDATE refund
SET refund_status = #{refundStatus}
WHERE refund_no = #{refundNo}

UPDATE refund_item
SET refund_status = #{refundStatus}
WHERE refund_no = #{refundNo}

UPDATE order_item
SET order_item_status = #{orderItemStatus}
WHERE order_item_no IN (
    SELECT order_item_no
    FROM refund_item
    WHERE refund_no = #{refundNo}
)

mapper.select:
SELECT COUNT(*) FROM refund r JOIN member m ON r.member_no = m.member_no WHERE 1 = 1
AND r.refund_status = #{status}
AND ( TO_CHAR(r.refund_no) LIKE '%' || #{keyword} || '%' OR TO_CHAR(r.order_no) LIKE '%' || #{keyword} || '%' OR LOWER(m.member_id) LIKE '%' || LOWER(#{keyword}) || '%' OR EXISTS ( SELECT 1 FROM refund_item ri2 JOIN order_item oi2 ON ri2.order_item_no = oi2.order_item_no WHERE ri2.refund_no = r.refund_no AND LOWER(oi2.item_name) LIKE '%' || LOWER(#{keyword}) || '%' ) )
